import{_ as t,o,c as d,a2 as r}from"./chunks/framework.YiAtXB4p.js";const p=JSON.parse('{"title":"ESI.ts Security Model","description":"","frontmatter":{"title":"ESI.ts Security Model","sourceFile":"guides/SECURITY-MODEL.md"},"headers":[],"relativePath":"guide/security-model.md","filePath":"guide/security-model.md"}'),a={name:"guide/security-model.md"};function s(i,e,n,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="esits-security-model" tabindex="-1">ESI.ts Security Model <a class="header-anchor" href="#esits-security-model" aria-label="Permalink to &quot;ESI.ts Security Model&quot;">​</a></h1><p>ESI.ts is a library embedded in someone else&#39;s application, so it has one trust boundary: the consumer&#39;s code and configuration are trusted, and every byte that arrives from the network is not. The library&#39;s job is to stop network data, and end-user values passed through the consumer, from choosing where a request goes, which token it carries, whose cache entry is served, or what reaches a log.</p><p>This is the scope statement for reporters, scanners, agents and the maintainer. <a href="https://github.com/lgriffin/ESI.ts/blob/master/SECURITY.md" target="_blank" rel="noreferrer"><code>SECURITY.md</code></a> says how to report and <a href="./security"><code>guides/SECURITY.md</code></a> lists the controls; this document adds what both lack: who is trusted, what is claimed, what is disclaimed, and a closed set of triage outcomes. The machine-readable index of this document is <a href="https://github.com/lgriffin/ESI.ts/blob/master/guides/security-model.yaml" target="_blank" rel="noreferrer"><code>guides/security-model.yaml</code></a>; the prose is canonical and <code>npm run security:model</code> holds the two together.</p><p>The structure is distilled from the Apache Camel security model into seven moves:</p><ol><li>Name every role and give it a trust level.</li><li>Draw the boundary and list the untrusted inputs, including what a trusted service reports back.</li><li>State the claimed properties as a table, each with a severity and a test.</li><li>State the properties not provided, and the false friends that look like one.</li><li>List in-scope vulnerability classes and the out-of-scope positions.</li><li>Keep a list of known non-findings and a closed set of dispositions, where an unclassifiable report forces a revision of this document.</li><li>Publish a machine-readable index and gate it in CI, so the prose cannot drift from the code.</li></ol><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to &quot;Trust model&quot;">​</a></h2><p>The consumer is fully trusted and ESI is trusted only to hold data: what it sends back is input.</p><table tabindex="0"><thead><tr><th>Role</th><th>Trust</th><th>What follows</th></tr></thead><tbody><tr><td>Maintainer and release pipeline</td><td>Trusted</td><td>Chooses defaults and publishes. The library relies on them for safe defaults.</td></tr><tr><td>Consumer developer: application code, middleware, a custom fetch, token storage, logger</td><td>Fully trusted</td><td>May set <code>unsafeAllowCustomHost</code> or <code>validateResponse: false</code>. Anything consumer code does is by design.</td></tr><tr><td>The consumer&#39;s end users, whose values the application passes as parameters</td><td>Untrusted</td><td>Their values reach <code>buildEndpointPath</code>. This is the primary attacker.</td></tr><tr><td>A third party handing the application a token</td><td>Untrusted</td><td>Claims count only after <code>verifyAccessToken</code>, or after ESI accepts the token.</td></tr><tr><td>ESI and EVE SSO</td><td>Trusted to hold data, untrusted for what they return</td><td>Bodies, <code>X-Pages</code>, cursors, ETag, Expires, redirect targets, token responses and the JWKS are all input.</td></tr><tr><td>SDE download host</td><td>Trusted to hold data, untrusted for what it returns</td><td>Archive entry names, YAML content and the build number are input.</td></tr><tr><td>Network path attacker</td><td>Untrusted</td><td>HTTPS is enforced with no off switch.</td></tr><tr><td>Other code in the same process</td><td>Outside the model</td><td>The library is not a sandbox.</td></tr></tbody></table><h3 id="untrusted-inputs-and-where-each-one-enters" tabindex="-1">Untrusted inputs and where each one enters <a class="header-anchor" href="#untrusted-inputs-and-where-each-one-enters" aria-label="Permalink to &quot;Untrusted inputs and where each one enters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Input</th><th>Enters at</th><th>Must never</th></tr></thead><tbody><tr><td>Path and query parameters</td><td><code>validatePathParam</code>, <code>validateQueryParam</code> in <code>src/core/util/validation.ts</code></td><td>Change the route or the host</td></tr><tr><td>Response body</td><td>Zod schemas under <code>src/schemas</code>, when <code>validateResponse</code> is on</td><td>Be returned as a typed value it does not match</td></tr><tr><td><code>X-Pages</code> and cursor tokens</td><td><code>src/core/pagination/</code>, <code>src/core/util/headersUtil.ts</code></td><td>Drive unbounded work, or be sent anywhere but back to the same host as an encoded query value</td></tr><tr><td>ETag, Expires</td><td><code>src/core/cache/</code></td><td>Serve one identity&#39;s entry to another</td></tr><tr><td>JWT claims</td><td><code>src/auth/jwt.ts</code>, <code>src/auth/jwks.ts</code></td><td>Be believed before the signature or ESI&#39;s acceptance</td></tr><tr><td>Redirect target</td><td>The fetch in <code>src/core/requestPipeline/fetchExecution.ts</code></td><td>Carry the token or the request off the allowlisted host</td></tr><tr><td>SDE archive and build info</td><td><code>src/sde/ingestion/</code></td><td>Write outside the directory the caller named</td></tr><tr><td>URLs and error text</td><td><code>sanitizeUrl</code>, <code>src/core/logger/redactLog.ts</code></td><td>Put a credential in a log line or an error</td></tr></tbody></table><h3 id="adversary" tabindex="-1">Adversary <a class="header-anchor" href="#adversary" aria-label="Permalink to &quot;Adversary&quot;">​</a></h3><p>The attacker controls parameter values, any token they hand over, and whatever ESI, SSO or the SDE host can be made to return. The attacker does not have code execution in the consumer&#39;s process, the consumer&#39;s configuration, its token storage or its filesystem. A report that needs one of those is out of model.</p><h2 id="security-properties-claimed" tabindex="-1">Security properties claimed <a class="header-anchor" href="#security-properties-claimed" aria-label="Permalink to &quot;Security properties claimed&quot;">​</a></h2><p>Eleven properties are claimed for the default configuration. A property the index marks <code>status: gap</code> is claimed but not yet held: its gap is recorded under <a href="#rollout-and-open-gaps">Rollout and open gaps</a> with an issue and an expiry date, and a report that reaches it is triaged against that gap. Severity is the tier a violation starts at, not a score.</p><table tabindex="0"><thead><tr><th>ID</th><th>Property</th><th>A violation looks like</th><th>Severity</th><th>Verified by</th></tr></thead><tbody><tr><td>P1</td><td>A token goes only to the allowlisted HTTPS host, and only on endpoints whose definition sets <code>requiresAuth</code></td><td>An Authorization header on a public endpoint or on another host</td><td>Critical</td><td><code>tests/tdd/core/security.test.ts</code>, <code>npm run validate:auth-scopes</code></td></tr><tr><td>P2</td><td>An untrusted parameter cannot change the route or the host</td><td><code>..</code>, <code>?</code>, <code>#</code> or <code>@</code> in a parameter reaching a different ESI route</td><td>High</td><td><code>security.test.ts</code>, <code>tests/fuzz/parameter-fuzz.test.ts</code>, feature <code>0059-path-parameters</code></td></tr><tr><td>P3</td><td>A token never appears in a log line, an error, a URL or a cache key</td><td>A bearer token or refresh token in output a user would paste into a bug report</td><td>High</td><td>CHARTER SEC-02 evidence, <code>tests/tdd/core/redactLog.test.ts</code>, feature <code>0058-logging</code></td></tr><tr><td>P4</td><td>One identity is never served another&#39;s cached body or ETag, and an unverified claim grants nothing</td><td>A forged token naming a character reads that character&#39;s cache</td><td>Critical</td><td><code>tests/tdd/core/cacheKey.test.ts</code>, <code>tests/fuzz/cache-key.property.test.ts</code></td></tr><tr><td>P5</td><td><code>verifyAccessToken</code> accepts a token only with an RS256 signature from EVE SSO&#39;s key set, the right issuer and audience, and an unexpired <code>exp</code></td><td>Algorithm confusion, a missing audience check, a key from another URL</td><td>Critical</td><td><code>tests/tdd/auth/jwks.test.ts</code>, <code>tests/tdd/auth/jwt.test.ts</code></td></tr><tr><td>P6</td><td>Values a response supplies (cursor, page count, redirect target) never select a host and never carry the token off the allowlisted host</td><td>A redirect or cursor that sends a request elsewhere</td><td>High</td><td>Feature <code>0062-security-boundary</code> (<code>@sec-P6</code>)</td></tr><tr><td>P7</td><td>With validation on, a body that does not match its schema is an error, never a typed value</td><td>Drifted or hostile JSON returned as a typed object</td><td>Medium</td><td>Feature <code>0053-runtime-validation</code>, <code>tests/fuzz/schema-fuzz.test.ts</code></td></tr><tr><td>P8</td><td>A count reported by the remote bounds no more than 1,000 page requests, at every pagination entry point</td><td><code>X-Pages: 100000000</code> starting that many requests</td><td>Medium</td><td>Feature <code>0062-security-boundary</code> (<code>@sec-P8</code>), <code>paginationOrchestration.test.ts</code>, <code>PaginationHandler.test.ts</code></td></tr><tr><td>P9</td><td>SDE ingestion writes only inside the directory the caller named</td><td>An archive entry landing outside the output directory</td><td>High</td><td>Feature <code>0062-security-boundary</code> (<code>@sec-P9</code>), <code>tests/tdd/sde/ingestion/SdeExtractor.test.ts</code></td></tr><tr><td>P10</td><td>The token file is written atomically with mode <code>0o600</code></td><td>A world-readable token file, or a torn write</td><td>Medium</td><td><code>tests/tdd/auth/FileTokenStorage.test.ts</code></td></tr><tr><td>P11</td><td>The published tarball is what this repository&#39;s workflow built: provenance, cosign bundle, SBOM</td><td>A release asset with no verifiable origin</td><td>High</td><td><code>release.yml</code>, <code>tests/tdd/workflows/workflow-permissions.test.ts</code> (SEC-03 to SEC-06)</td></tr></tbody></table><p>All eleven are claimed with zero security configuration. A violation reachable only after the consumer sets an unsafe option is out of model. P6, P8 and P9 had gaps when this document was first read against the code; they were closed by <a href="https://github.com/lgriffin/ESI.ts/pull/629" target="_blank" rel="noreferrer">#629</a>, and the index holds no gap today.</p><p>P12 is retired, not renumbered: it claimed that SDE content never altered the structure of the SQL <code>SdeDatabaseBuilder</code> built. The builder, the only code in the library that built SQL, was removed after 12.2.0 with the <code>better-sqlite3</code> optional peer, so there is nothing left for the property to hold. The id is not reused. A report against a release that still ships the builder (12.2.0 and earlier) is triaged against P12 as it stood there.</p><h2 id="properties-not-provided" tabindex="-1">Properties not provided <a class="header-anchor" href="#properties-not-provided" aria-label="Permalink to &quot;Properties not provided&quot;">​</a></h2><p>Listing what is not claimed is what makes the scope a closed set: a report that says &quot;feature X failed to do Y&quot; can be answered with &quot;X was not built to do Y&quot;.</p><ul><li><strong>D1 · No sandbox for consumer code.</strong> Middleware, interceptors, a custom fetch, a custom token storage and a custom logger see every request, response and token.</li><li><strong>D2 · No availability guarantee.</strong> The rate limiter and circuit breaker protect ESI from the client. Beyond the page cap in P8, resource use under hostile responses is the consumer&#39;s to bound.</li><li><strong>D3 · No protection once an opt-out is set.</strong> <code>unsafeAllowCustomHost: true</code> removes the host check; <code>validateResponse: false</code> removes P7.</li><li><strong>D4 · No sanitisation of strings ESI returns.</strong> Character names, mail bodies and descriptions are returned as received. Escaping them for HTML or SQL is the consumer&#39;s job.</li><li><strong>D5 · No encryption at rest.</strong> <code>FileTokenStorage</code> is plain text protected by file mode only.</li><li><strong>D6 · No redaction of secrets the consumer adds.</strong> Redaction covers a fixed list of URL query parameters, not headers or bodies a consumer builds.</li><li><strong>D7 · No shield against a dependency advisory that this code does not reach.</strong> The audit gate decides exploitability; the advisory belongs upstream.</li><li><strong>D8 · No constant-time comparison.</strong></li><li><strong>D9 · No integrity check on the SDE archive.</strong> CCP publishes no digest for the export, so the download is trusted to hold data like ESI is; P9 bounds where its entries land, and the download is bounded in size.</li></ul><h3 id="false-friends" tabindex="-1">False friends <a class="header-anchor" href="#false-friends" aria-label="Permalink to &quot;False friends&quot;">​</a></h3><ul><li><code>decodeAccessToken</code> decodes, it does not verify. Only <code>verifyAccessToken</code> checks a signature.</li><li>The host allowlist is checked once, on the base URL at construction. It says nothing about where a redirect leads; P6 is held by refusing redirects in the fetch itself.</li><li><code>sanitizeUrl</code> is a redactor for eleven named query parameters. It is not a general secret scrubber.</li><li><code>validatePathParam</code> protects the route. It does not make a value safe for the consumer&#39;s own use.</li><li>Zod validation detects drift. Passthrough keeps unknown fields, and a well-shaped value can still be false.</li><li><code>requiresAuth</code> is generated from the specification. A wrong flag is a token leak, which is why <code>validate:auth-scopes</code> exists.</li><li>The Scorecard number measures pipeline hygiene. It makes no statement about runtime behaviour.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>A report is in scope when it shows the library, in its default configuration, letting an untrusted input break one of P1 to P11.</p><h3 id="in-scope-classes" tabindex="-1">In-scope classes <a class="header-anchor" href="#in-scope-classes" aria-label="Permalink to &quot;In-scope classes&quot;">​</a></h3><ul><li><strong>Token exfiltration.</strong> A token sent to a public endpoint, another host, a redirect target, a log, an error or a cache key (P1, P3, P6).</li><li><strong>Route or host injection.</strong> A parameter, cursor or header value that changes where a request goes (P2, P6).</li><li><strong>Cross-identity disclosure.</strong> A cached body, ETag or in-flight response served under the wrong identity, including through state shared by two clients in one process (P4).</li><li><strong>Verification bypass.</strong> Any way <code>verifyAccessToken</code> accepts a token EVE SSO did not sign for this client (P5).</li><li><strong>Path traversal.</strong> An archive entry or storage path escaping its directory (P9, P10).</li><li><strong>Insecure default.</strong> Any of the above reachable by constructing a client and making a call, with no option set.</li><li><strong>Published artefact integrity.</strong> A release whose provenance, signature or SBOM does not verify (P11).</li></ul><p>A guard that exists in the source but is not on the live path counts as absent. A guard applied at one entry point and not at its sibling is a gap, not a configuration difference.</p><h3 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h3><ul><li>Anything consumer code does: middleware, interceptors, a custom fetch, a custom storage.</li><li>Behaviour that needs <code>unsafeAllowCustomHost: true</code> or <code>validateResponse: false</code>.</li><li>Denial of service by volume or response size, beyond the page cap in P8.</li><li>Vulnerabilities in ESI or EVE SSO; report those to CCP Games.</li><li>Cross-site scripting in a consumer application that renders ESI strings unescaped.</li><li>Query injection. The library builds no SQL since the release after 12.2.0 (P12, retired); SQL a consumer builds from ESI or SDE strings is the consumer&#39;s to escape (D4).</li><li>An advisory in a development dependency, <code>docs-site/</code> or <code>examples/</code> that never ships in the tarball.</li><li>The local scripts under <code>scripts/auth/</code>, which use a loopback callback by design.</li><li>Versions 7.x and 8.x, which are unsupported.</li></ul><h2 id="triage" tabindex="-1">Triage <a class="header-anchor" href="#triage" aria-label="Permalink to &quot;Triage&quot;">​</a></h2><p>Every report, scanner finding or agent review ends in exactly one of nine dispositions, each citing a section of this document. Closed reports are logged one line each in <a href="./security-triage-log"><code>guides/security-triage-log.md</code></a>.</p><table tabindex="0"><thead><tr><th>Disposition</th><th>Meaning</th><th>Licensed by</th></tr></thead><tbody><tr><td><code>VALID</code></td><td>An untrusted input breaks a claimed property in the default configuration. Fixed, released, published as a GitHub Security Advisory.</td><td>Security properties claimed, In-scope classes</td></tr><tr><td><code>VALID-HARDENING</code></td><td>No claimed property is broken, but the default is tightened anyway. Shipped with a changelog entry, usually no advisory.</td><td>Maintainer discretion</td></tr><tr><td><code>OUT-OF-MODEL: trusted-input</code></td><td>Needs control of consumer code or configuration.</td><td>Trust model</td></tr><tr><td><code>OUT-OF-MODEL: adversary-not-in-scope</code></td><td>Needs a capability the adversary section excludes.</td><td>Adversary</td></tr><tr><td><code>OUT-OF-MODEL: opt-in</code></td><td>Appears only with an unsafe option or validation turned off.</td><td>Out of scope</td></tr><tr><td><code>OUT-OF-MODEL: unsupported</code></td><td>Affects only 7.x, 8.x, examples or the docs site.</td><td>Out of scope</td></tr><tr><td><code>BY-DESIGN: property-disclaimed</code></td><td>Concerns a property this document says is not provided.</td><td>Properties not provided</td></tr><tr><td><code>KNOWN-NON-FINDING</code></td><td>Matches an entry in the list below.</td><td>Known non-findings</td></tr><tr><td><code>MODEL-GAP</code></td><td>Fits none of the above. The response is a pull request against this document, not an ad hoc call.</td><td>This section</td></tr></tbody></table><p>An incomplete fix is a new finding with its own advisory. &quot;Already fixed in an earlier release&quot; is not a disposition: the question is whether the path in the new report is closed.</p><h3 id="known-non-findings" tabindex="-1">Known non-findings <a class="header-anchor" href="#known-non-findings" aria-label="Permalink to &quot;Known non-findings&quot;">​</a></h3><ul><li><strong>N1 · &quot;<code>unsafeAllowCustomHost</code> allows SSRF.&quot;</strong> A named opt-in whose name is meant to show in code review.</li><li><strong>N2 · &quot;<code>decodeAccessToken</code> does not verify the signature.&quot;</strong> Documented. The cache counts a claim only after ESI accepts the token.</li><li><strong>N3 · &quot;The cache key uses a truncated SHA-256.&quot;</strong> It partitions a cache; it authenticates nothing. A finding needs a demonstrated collision that crosses identities.</li><li><strong>N4 · &quot;The token script listens on <code>http://localhost</code>.&quot;</strong> A loopback PKCE callback in a developer script.</li><li><strong>N5 · &quot;A token is stored in <code>.env</code>.&quot;</strong> Git-ignored local state; <code>.env.example</code> holds no values.</li><li><strong>N6 · &quot;Zod passthrough accepts unknown fields.&quot;</strong> By design, so new ESI fields do not break consumers.</li><li><strong>N7 · &quot;Dependency X has an advisory.&quot;</strong> In scope only if X is <code>pino</code> or <code>zod</code>, or an optional SDE peer, and the vulnerable path is reachable from library code.</li><li><strong>N8 · &quot;The library does not rate-limit hostile input.&quot;</strong> Availability is disclaimed.</li></ul><p>This list is written to be handed to a scanner or an agent as a suppression set; <code>guides/security-model.yaml</code> carries it as <code>non_findings</code>.</p><h2 id="technical-implementation" tabindex="-1">Technical implementation <a class="header-anchor" href="#technical-implementation" aria-label="Permalink to &quot;Technical implementation&quot;">​</a></h2><p>The model becomes rigid through seven additions that reuse machinery the repository already has: the spec audit&#39;s fixture pattern, the audit-exception expiry rule, the charter, and <code>ci-success</code>. All seven are in place; <a href="#rollout-and-open-gaps">Rollout and open gaps</a> records the order they landed in.</p><table tabindex="0"><thead><tr><th>Add</th><th>What it does</th></tr></thead><tbody><tr><td><code>guides/SECURITY-MODEL.md</code></td><td>This document. The prose is canonical.</td></tr><tr><td><code>guides/security-model.yaml</code></td><td>Derived index of roles, inputs, properties, disclaimed properties, non-findings and dispositions. Read by the audit script, scanners and agents.</td></tr><tr><td><code>scripts/quality/security-model-audit.ts</code>, run as <code>npm run security:model</code></td><td>The gate. Negative fixtures under <code>tests/tdd/scripts/fixtures/security-model/</code>, one per rule below.</td></tr><tr><td><code>tests/bdd/features/core/0062-security-boundary.feature</code></td><td>One Rule per property it holds, in the unwanted-behaviour form.</td></tr><tr><td><code>tests/tdd/core/untrusted-input-sites.test.ts</code></td><td>Discovers every network call and every response-header read under <code>src/</code> and fails when one is missing from the index.</td></tr><tr><td><code>guides/security-triage-log.md</code></td><td>One line per closed report: date, source, disposition, section cited.</td></tr><tr><td>CHARTER rows SEC-09 to SEC-12, and a <code>security-model</code> job in the needs of <code>ci-success</code></td><td>Makes the four rules below requirements with a status.</td></tr></tbody></table><h3 id="what-the-audit-fails-on" tabindex="-1">What the audit fails on <a class="header-anchor" href="#what-the-audit-fails-on" aria-label="Permalink to &quot;What the audit fails on&quot;">​</a></h3><ul><li>A property in the prose table that is missing from the index, or the reverse, or a different severity (SEC-09).</li><li>A claimed property with no Rule tagged with its id in the feature files, no existing test file, or a gap with no issue, no expiry date, or an expired date; the count of gaps may only shrink against <code>master</code> (SEC-10).</li><li>A Rule that claims a disclaimed property.</li><li>A network call site or response-header read in <code>src/</code> that the index does not list, or an input with no hostile-value generator (SEC-11).</li><li>A non-finding whose cited section does not exist, or a triage-log line whose disposition is outside the closed set (SEC-12).</li></ul><h3 id="for-agents-and-scanners" tabindex="-1">For agents and scanners <a class="header-anchor" href="#for-agents-and-scanners" aria-label="Permalink to &quot;For agents and scanners&quot;">​</a></h3><p><code>AGENTS.md</code> and <code>CLAUDE.md</code> carry one paragraph: review security against <code>guides/security-model.yaml</code>, treat <code>non_findings</code> as suppressions, and end every finding with a disposition from the closed set.</p><h2 id="rollout-and-open-gaps" tabindex="-1">Rollout and open gaps <a class="header-anchor" href="#rollout-and-open-gaps" aria-label="Permalink to &quot;Rollout and open gaps&quot;">​</a></h2><p>Reading master <code>f527e88</code> (v11.2.0) against the model found three gaps. Each got a failing scenario before its fix, and all three are closed (<a href="https://github.com/lgriffin/ESI.ts/pull/629" target="_blank" rel="noreferrer">#629</a>). A gap found later is recorded here and in the index with <code>status: gap</code>, an issue and an expiry date.</p><table tabindex="0"><thead><tr><th>#</th><th>Gap</th><th>Where</th><th>Property</th><th>Handling</th></tr></thead><tbody><tr><td>1</td><td><code>X-Pages</code> is read with no cap in the async iterators, while two other paths cap at 1,000</td><td><code>src/core/pagination/AsyncPaginationIterator.ts</code></td><td>P8</td><td><code>VALID-HARDENING</code>: one shared bounded page count used by every path</td></tr><tr><td>2</td><td>No fetch in <code>src/</code> sets a redirect option, so redirects are followed; the allowlist is checked on the base URL only</td><td><code>src/core/requestPipeline/fetchExecution.ts</code></td><td>P6</td><td>Refuse redirects. Node&#39;s fetch drops <code>Authorization</code> on a cross-origin redirect, so this is hardening: the request, not the token, would have left</td></tr><tr><td>3</td><td>The SDE download has no size bound, and <code>extractAll</code> hands entry names to adm-zip with a peer floor of 0.4.11</td><td><code>src/sde/ingestion/SdeDownloader.ts</code>, <code>SdeExtractor.ts</code></td><td>P9</td><td>Check every entry name against the output directory before extracting, with a hostile-archive fixture; bound the download size</td></tr></tbody></table><p><code>SdeDatabaseBuilder</code> read clean against the query-injection class (P12): values were bound through prepared statements and column names quoted with doubled quotes. The builder was removed after 12.2.0 and P12 retired with it.</p><p>Rollout, tracked by <a href="https://github.com/lgriffin/ESI.ts/issues/627" target="_blank" rel="noreferrer">#627</a>:</p><ol><li>Land this document, the index, a link from <code>SECURITY.md</code> and the agent pointer. Documentation only. Done in <a href="https://github.com/lgriffin/ESI.ts/pull/628" target="_blank" rel="noreferrer">#628</a>.</li><li>Fix gaps 1 to 3, each with its Rule in feature 0062. Done in <a href="https://github.com/lgriffin/ESI.ts/pull/629" target="_blank" rel="noreferrer">#629</a>.</li><li>Land the audit script, its fixtures and the input-site test, add <code>security-model</code> to <code>ci-success</code>, and add SEC-09 to SEC-12 to the charter as Enforced. Done, with step 4.</li><li>Point the nightly payload fuzz and the fault catalogue at the input registry, so every registered input has a hostile-value generator. Done: each input in the index lists its <code>generators</code> (fuzz and unit test files, the nightly payload fuzz, and <code>fault:&lt;id&gt;</code> entries of the fault catalogue, which gains <code>x-pages-beyond-the-cap</code> and <code>redirect-to-another-host</code>); the audit fails an input with none, and the catalogue&#39;s self-test fails a reference to a fault it does not hold.</li></ol>',49)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
